* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #f5f2e9; background: #17192b; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 28px 16px; background: radial-gradient(ellipse at 50% 0%, #303355 0, #20233a 42%, #17192b 82%); }
button { font: inherit; }
.board { width: min(100%, 520px); padding: 30px; border: 1px solid #454967; border-radius: 18px; background: #242740; box-shadow: 0 22px 70px #0b0d1c99; }
.header { display: flex; align-items: center; gap: 16px; }
.pixel-mark { width: 54px; height: 54px; display: grid; place-items: center; border: 3px solid #17192b; outline: 2px solid #8fe3bd; background: #8fe3bd; color: #20233a; font-size: 32px; font-weight: 800; line-height: 1; box-shadow: inset -6px -6px 0 #68bb9b; }
.eyebrow, .summary-label, .list-heading, footer { letter-spacing: .12em; font-size: 12px; font-weight: 800; }
.eyebrow { margin: 0 0 3px; color: #8fe3bd; }
h1 { margin: 0; font-size: clamp(25px, 7vw, 32px); line-height: 1.15; }
.summary { display: flex; justify-content: space-between; gap: 16px; margin: 28px 0 25px; padding: 18px 20px; border: 1px solid #454967; border-radius: 12px; background: #1d2036; }
.summary div { display: grid; gap: 5px; }
.summary-label { color: #aaaec8; }
.summary strong { font-size: 20px; font-variant-numeric: tabular-nums; }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; color: #aaaec8; }
.list-heading h2 { margin: 0; font-size: 12px; }
.list-heading span { font-weight: 600; letter-spacing: 0; }
.playlist { display: grid; gap: 10px; margin: 0 0 20px; padding: 0; list-style: none; }
.track { display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 12px; border: 1px solid #414560; border-radius: 12px; background: #2c304a; }
.track-number { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 8px; background: #393e5d; color: #8fe3bd; font-size: 15px; font-weight: 800; font-variant-numeric: tabular-nums; }
.track-info { min-width: 0; }
.track-title { display: block; overflow: hidden; color: #f5f2e9; font-size: 16px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.track-duration { display: block; margin-top: 3px; color: #aaaec8; font-size: 14px; font-variant-numeric: tabular-nums; }
.track-controls { display: flex; gap: 5px; }
.icon-button { display: grid; place-items: center; min-width: 38px; min-height: 38px; padding: 0 8px; border: 1px solid #545a7c; border-radius: 8px; background: #242740; color: #f5f2e9; cursor: pointer; font-size: 18px; }
.icon-button:hover { border-color: #8fe3bd; background: #353b57; }
.icon-button:active, .shuffle-button:active { transform: translateY(2px); }
.icon-button:disabled { opacity: .38; cursor: not-allowed; }
.icon-button.remove:hover { border-color: #ff9292; color: #ffb0a5; }
.shuffle-button { width: 100%; min-height: 52px; border: 0; border-radius: 10px; background: #8fe3bd; color: #172b2b; cursor: pointer; font-size: 17px; font-weight: 800; box-shadow: inset 0 -4px 0 #68bb9b; }
.shuffle-button:hover { background: #a4f0cd; }
.shuffle-button span { margin-right: 8px; font-size: 22px; vertical-align: -1px; }
button:focus-visible { outline: 3px solid #ffd27a; outline-offset: 3px; }
footer { margin-top: 20px; color: #777e9f; text-align: center; font-size: 10px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 420px) { .board { padding: 22px 16px; } .summary { padding: 15px 14px; } .track { gap: 8px; padding: 10px 8px; } .track-controls { gap: 4px; } .icon-button { min-width: 34px; min-height: 36px; padding: 0 6px; } }

const songs = [
  { title: "Moonlit Arcade", duration: 203 },
  { title: "Soda Pop Skyline", duration: 187 },
  { title: "Cloud Garden", duration: 246 },
  { title: "Midnight Save Point", duration: 221 },
  { title: "Tiny Planet Dance", duration: 194 },
  { title: "Last Train Home", duration: 268 }
];

const playlist = document.querySelector("#playlist");
const count = document.querySelector("#song-count");
const total = document.querySelector("#total-time");
const note = document.querySelector("#list-note");
const status = document.querySelector("#status");

function formatTime(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const remainder = seconds % 60;
  return `${hours}:${String(minutes).padStart(2, "0")}:${String(remainder).padStart(2, "0")}`;
}

function render() {
  playlist.replaceChildren();
  songs.forEach((song, index) => {
    const row = document.createElement("li");
    row.className = "track";
    const number = document.createElement("span");
    number.className = "track-number";
    number.setAttribute("aria-hidden", "true");
    number.textContent = String(index + 1).padStart(2, "0");

    const info = document.createElement("span");
    info.className = "track-info";
    const title = document.createElement("span");
    title.className = "track-title";
    title.textContent = song.title;
    const duration = document.createElement("span");
    duration.className = "track-duration";
    duration.textContent = formatTime(song.duration);
    info.append(title, duration);

    const controls = document.createElement("span");
    controls.className = "track-controls";
    const up = makeButton("↑", `Move ${song.title} up`, "move-up", index === 0);
    const down = makeButton("↓", `Move ${song.title} down`, "move-down", index === songs.length - 1);
    const remove = makeButton("×", `Remove ${song.title}`, "remove");
    remove.classList.add("remove");
    controls.append(up, down, remove);
    row.append(number, info, controls);
    playlist.append(row);
  });

  const seconds = songs.reduce((sum, song) => sum + song.duration, 0);
  count.textContent = `${songs.length} ${songs.length === 1 ? "song" : "songs"}`;
  total.textContent = formatTime(seconds);
  note.textContent = `${songs.length} ${songs.length === 1 ? "track" : "tracks"}`;
}

function makeButton(label, accessibleName, action, disabled = false) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "icon-button";
  button.textContent = label;
  button.setAttribute("aria-label", accessibleName);
  button.dataset.action = action;
  button.disabled = disabled;
  return button;
}

playlist.addEventListener("click", (event) => {
  const button = event.target.closest("button[data-action]");
  if (!button) return;
  const row = button.closest("li");
  const index = Array.from(playlist.children).indexOf(row);
  const action = button.dataset.action;

  if (action === "remove") {
    const [removed] = songs.splice(index, 1);
    status.textContent = `Removed ${removed.title}.`;
  } else if (action === "move-up" && index > 0) {
    [songs[index - 1], songs[index]] = [songs[index], songs[index - 1]];
    status.textContent = `Moved ${songs[index - 1].title} up.`;
  } else if (action === "move-down" && index < songs.length - 1) {
    [songs[index + 1], songs[index]] = [songs[index], songs[index + 1]];
    status.textContent = `Moved ${songs[index + 1].title} down.`;
  }
  render();
});

document.querySelector("#shuffle").addEventListener("click", () => {
  for (let i = songs.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [songs[i], songs[j]] = [songs[j], songs[i]];
  }
  status.textContent = "Playlist shuffled.";
  render();
});

render();
